<?php

declare(strict_types=1);

namespace Konventix\Admission\Database\Factories;

use Illuminate\Database\Eloquent\Factories\Factory;
use Illuminate\Support\Str;
use Konventix\Admission\Models\Checkpoint;
use Konventix\Admission\Models\EntranceDevice;

/**
 * @extends Factory<EntranceDevice>
 */
class EntranceDeviceFactory extends Factory
{
    /**
     * The plaintext of the token most recently generated by this factory, so
     * a test can authenticate as the device it just made. Production code has
     * no equivalent — the plaintext is shown once at enrolment and dropped.
     */
    public static ?string $lastPlainToken = null;

    /** @var class-string<EntranceDevice> */
    protected $model = EntranceDevice::class;

    /**
     * No `brand_id` here on purpose: BelongsToBrand stamps it.
     *
     * @return array<string, mixed>
     */
    public function definition(): array
    {
        $plain = Str::random(48);
        self::$lastPlainToken = $plain;

        return [
            'checkpoint_id' => Checkpoint::factory(),
            'label' => fake()->randomElement(['Scanner A', 'Scanner B', 'Tablet 1']),
            'token_hash' => EntranceDevice::hashToken($plain),
            'last_seen_at' => null,
            'revoked_at' => null,
        ];
    }

    public function withToken(string $plainToken): static
    {
        return $this->state(fn (array $attributes): array => [
            'token_hash' => EntranceDevice::hashToken($plainToken),
        ]);
    }

    public function revoked(): static
    {
        return $this->state(fn (array $attributes): array => [
            'revoked_at' => now(),
        ]);
    }
}
